// PaletteRGB returns the colour of palette index i for the given Color Map value.
func PaletteRGB(colorMap, i int) [3]uint8 {
	if i < 0 || i > 127 {
		return [3]uint8{}
	}
	if colorMap == 1 {
		return PaletteExpanded[i]
	}
	return PaletteClassic[i]
}

// DetentRGB is the detent colour: 0..127 crossfades red to blue.
func DetentRGB(v int) [3]uint8 {
	v = min(max(v, 0), 127)
	return [3]uint8{uint8(255 * (127 - v) / 127), 0, uint8(255 * v / 127)}
}
